package com.company.tpm.dashboard;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/dashboard")public class DashboardController{private final AnalyticsService analytics;DashboardController(AnalyticsService s){analytics=s;}@GetMapping@PreAuthorize("isAuthenticated()")AnalyticsService.Metrics metrics(){return analytics.metrics();}}